17: template <typename scalar_t>
18: void host_lfilter_core_loop(
19:     const Tensor& input_signal_windows,
20:     const Tensor& a_coeff_flipped,
21:     Tensor& padded_output_waveform) {
22:   int64_t n_batch = input_signal_windows.size(0);
23:   int64_t n_channel = input_signal_windows.size(1);
24:   int64_t n_samples_input = input_signal_windows.size(2);
25:   int64_t n_samples_output = padded_output_waveform.size(2);
26:   int64_t n_order = a_coeff_flipped.size(1);
27:   scalar_t* output_data = padded_output_waveform.mutable_data_ptr<scalar_t>();
28:   const scalar_t* input_data = input_signal_windows.const_data_ptr<scalar_t>();
29:   const scalar_t* a_coeff_flipped_data =
30:       a_coeff_flipped.const_data_ptr<scalar_t>();
31: 
32:   torch::stable::parallel_for(
33:       0, n_channel * n_batch, 1, [&](int64_t begin, int64_t end) {
34:         for (auto i = begin; i < end; i++) {
35:           int64_t offset_input = i * n_samples_input;
36:           int64_t offset_output = i * n_samples_output;
37:           int64_t i_channel = i % n_channel;
38:           for (int64_t i_sample = 0; i_sample < n_samples_input; i_sample++) {
39:             scalar_t a0 = input_data[offset_input + i_sample];
40:             for (int64_t i_coeff = 0; i_coeff < n_order; i_coeff++) {
41:               a0 -= output_data[offset_output + i_sample + i_coeff] *
42:                   a_coeff_flipped_data[i_coeff + i_channel * n_order];
43:             }
44:             output_data[offset_output + i_sample + n_order - 1] = a0;
45:           }
46:         }
47:       });
48: }
