50: Tensor cpu_lfilter_core_loop(
51:     Tensor input_signal_windows,
52:     Tensor a_coeff_flipped,
53:     Tensor padded_output_waveform) {
54:   STD_TORCH_CHECK(
55:       input_signal_windows.is_cpu() && a_coeff_flipped.is_cpu() &&
56:       padded_output_waveform.is_cpu());
57: 
58:   STD_TORCH_CHECK(
59:       input_signal_windows.is_contiguous() && a_coeff_flipped.is_contiguous() &&
60:       padded_output_waveform.is_contiguous());
61: 
62:   STD_TORCH_CHECK(
63:       (input_signal_windows.scalar_type() == ScalarType::Float ||
64:        input_signal_windows.scalar_type() == ScalarType::Double) &&
65:       (a_coeff_flipped.scalar_type() == ScalarType::Float ||
66:        a_coeff_flipped.scalar_type() == ScalarType::Double) &&
67:       (padded_output_waveform.scalar_type() == ScalarType::Float ||
68:        padded_output_waveform.scalar_type() == ScalarType::Double));
69: 
70:   STD_TORCH_CHECK(
71:       input_signal_windows.size(0) == padded_output_waveform.size(0));
72:   STD_TORCH_CHECK(
73:       input_signal_windows.size(1) == padded_output_waveform.size(1));
74: 
75:   STD_TORCH_CHECK(
76:       input_signal_windows.size(2) + a_coeff_flipped.size(1) - 1 ==
77:       padded_output_waveform.size(2));
78: 
79:   THO_DISPATCH_V2(
80:       input_signal_windows.scalar_type(),
81:       "lfilter_core_loop",
82:       [&] {
83:         host_lfilter_core_loop<scalar_t>(
84:             input_signal_windows, a_coeff_flipped, padded_output_waveform);
85:       },
86:       AT_FLOATING_TYPES);
87:   return padded_output_waveform;
88: }
