90: Tensor lfilter_core_generic_loop(
91:     Tensor input_signal_windows,
92:     Tensor a_coeff_flipped,
93:     Tensor padded_output_waveform) {
94:   int64_t n_samples_input = input_signal_windows.size(2);
95:   int64_t n_order = a_coeff_flipped.size(1);
96:   auto coeff = torch::stable::unsqueeze(a_coeff_flipped, 2);
97:   for (int64_t i_sample = 0; i_sample < n_samples_input; i_sample++) {
98:     auto windowed_output_signal = torch::stable::transpose(
99:         torch::stable::narrow(padded_output_waveform, 2, i_sample, n_order),
100:         0,
101:         1);
102:     auto o0 = torch::stable::subtract(
103:         torch::stable::select(input_signal_windows, 2, i_sample),
104:         torch::stable::transpose(
105:             torch::stable::squeeze(
106:                 torch::stable::matmul(windowed_output_signal, coeff), 2),
107:             0,
108:             1));
109:     auto s = torch::stable::select(
110:         padded_output_waveform, 2, i_sample + n_order - 1);
111:     torch::stable::copy_(s, o0);
112:   }
113:   return padded_output_waveform;
114: }
