18:   int64_t n_frames = waveform_accessor.size(1);
19:   int64_t n_channels = waveform_accessor.size(0);
20: 
21:   torch::stable::parallel_for(
22:       0, n_channels, 1, [&](int64_t begin, int64_t end) {
23:         for (int64_t i_channel = begin; i_channel < end; ++i_channel) {
24:           for (int64_t i_frame = 0; i_frame < n_frames; ++i_frame) {
25:             last_out_accessor[i_channel] = temp_accessor[i_channel][i_frame] -
26:                 last_in_accessor[i_channel] +
27:                 0.995 * last_out_accessor[i_channel];
28:             last_in_accessor[i_channel] = temp_accessor[i_channel][i_frame];
29:             output_waveform_accessor[i_channel][i_frame] =
30:                 waveform_accessor[i_channel][i_frame] * 0.5 +
31:                 last_out_accessor[i_channel] * 0.75;
32:           }
33:         }
34:       });
35: }
